import {Circuit} from '../../src/runtime/numeric-ui-core.ts'

/** CPU spring-force assembly + actual Handwired CPU/WebGPU Verlet integration.
 * Constraints, self-collision and spring gathering are NOT automatically generated by this circuit.
 */
export const CLOTH_SOURCE_SIZE=8
export const CLOTH_STATE_SIZE=4
export const clothPhysics={inertia:0.984,forceStep:0.008} as const
export function buildClothCircuit() {
  const c=new Circuit(CLOTH_SOURCE_SIZE)
  const s=Array.from({length:CLOTH_SOURCE_SIZE},(_,index)=>c.source(index))
  const {inertia,forceStep}=clothPhysics
  // x(t+1) = x + inertia * (x - previousX) + dt2 * (springForceX + wind)
  const x=c.roundAffine([[s[0]!,1+inertia],[s[2]!,-inertia],
    [s[4]!,forceStep],[s[6]!,forceStep]])
  const y=c.roundAffine([[s[1]!,1+inertia],[s[3]!,-inertia],
    [s[5]!,forceStep],[s[7]!,forceStep]])
  return {circuit:c,outputs:{x,y},outputWires:[x,y] as const}
}
export function handwrittenClothStep(input:Float32Array) {
  if(input.length!==CLOTH_SOURCE_SIZE)throw new Error('expected 8 cloth sources')
  const f=Math.fround,{inertia,forceStep}=clothPhysics
  const axis=(index:number,prev:number,force:number,external:number)=>{
    let sum=f(f(input[index]! * f(1+inertia)) + f(input[prev]! * f(-inertia)))
    sum=f(sum+f(input[force]! * f(forceStep)))
    return f(sum+f(input[external]! * f(forceStep)))
  }
  return Float32Array.of(axis(0,2,4,6),axis(1,3,5,7))
}
